"""Run from repo root: python3 chart_apply.py  (idempotent; keeps your other edits)"""
PAIRS = [('});\nconst d = c\n.map(\n(v, i) =>\n(i ? "L" : "M") + X(f[i]).toFixed(1) + " " + Y(v).toFixed(1),\n)\n.join(""),', '});\nconst d = window.HAChart.smooth(c.map((v, i) => [X(f[i]), Y(v)])),'), ('.join("");\nsv.innerHTML = `<defs><linearGradient id="hvA" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="var(--acc)" stop-opacity=".30"/><stop offset="1" stop-color="var(--acc)" stop-opacity="0"/></linearGradient></defs>\n <g stroke="var(--bd)" fill="none"><path d="M40 50H500M40 100H500M40 200H500M40 250H500" stroke-dasharray="2 5"/><path d="M40 150H500" stroke="var(--bd2)"/></g>\n <path d="${d}L500 150L40 150Z" fill="url(#hvA)"/><path d="${d}" fill="none" stroke="var(--acc)" stroke-width="9" stroke-linecap="round" opacity=".12"/><path d="${d}" fill="none" stroke="var(--acc)" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>\n <line x1="${px}" x2="${px}" y1="40" y2="260" stroke="var(--tx)" stroke-opacity=".28"/><circle cx="${px}" cy="${py}" r="5" fill="var(--acc)" stroke="var(--bg)" stroke-width="2"/>', '.join("");\nsv.innerHTML = `<defs><linearGradient id="hvA" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="var(--acc)" stop-opacity=".30"/><stop offset=".6" stop-color="var(--acc)" stop-opacity=".07"/><stop offset="1" stop-color="var(--acc)" stop-opacity="0"/></linearGradient><linearGradient id="hvL" x1="0" y1="0" x2="1" y2="0"><stop offset="0" stop-color="var(--acc)" stop-opacity=".75"/><stop offset=".5" stop-color="var(--acc)"/><stop offset="1" stop-color="var(--acc)" stop-opacity=".75"/></linearGradient><filter id="hvG" x="-5%" y="-30%" width="110%" height="160%"><feGaussianBlur stdDeviation="4"/></filter></defs>\n <g stroke="var(--tx)" fill="none"><path d="M40 50H500M40 100H500M40 200H500M40 250H500" stroke-opacity=".07"/><path d="M40 150H500" stroke-opacity=".28"/></g>\n <path d="${d}L500 150L40 150Z" fill="url(#hvA)"/><path d="${d}" fill="none" stroke="var(--acc)" stroke-width="7" stroke-linecap="round" opacity=".45" filter="url(#hvG)"/><path d="${d}" fill="none" stroke="url(#hvL)" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"/>\n <line x1="${px}" x2="${px}" y1="40" y2="260" stroke="var(--tx)" stroke-opacity=".28"/><circle cx="${px}" cy="${py}" r="11" fill="var(--acc)" opacity=".16"/><circle cx="${px}" cy="${py}" r="5" fill="var(--acc)" stroke="var(--bg)" stroke-width="2"/>'), ('pts: pts(cv.target),\ncolor: "var(--tx)",\nw: 1.6,\ndash: "5 4",', 'pts: pts(cv.target),\ncolor: "var(--ch-tgt)",\nw: 1.5,\ndash: "5 5",')]
CSS = '/* ===== charts v2: steel / amber / ivory ===== */\n:root{--s-raw:#8FA4C2;--ch-tgt:#E3DBC8}\n:root[data-theme="light"]{--s-raw:#5A7394;--ch-tgt:#4B4435}\n.chartbox{background:radial-gradient(120% 100% at 50% 0%,color-mix(in srgb,var(--acc) 7%,transparent),transparent 62%),linear-gradient(180deg,color-mix(in srgb,var(--tx) 3%,var(--deep)),var(--deep));\n border:1px solid var(--bd2);border-radius:var(--r-lg,16px);box-shadow:inset 0 1px 0 color-mix(in srgb,var(--tx) 8%,transparent),var(--e2,none)}\n.chartbox svg text{font-family:var(--mono)}\n.tip{background:color-mix(in srgb,var(--surface) 88%,transparent);backdrop-filter:blur(14px) saturate(1.3);-webkit-backdrop-filter:blur(14px) saturate(1.3);\n border:1px solid color-mix(in srgb,var(--tx) 14%,transparent);border-radius:12px;padding:10px 12px 11px;box-shadow:0 14px 34px -12px rgba(0,0,0,.65),inset 0 1px 0 color-mix(in srgb,var(--tx) 8%,transparent);min-width:168px}\n.tip > b{padding-bottom:7px;margin-bottom:7px;border-bottom:1px solid var(--bd);color:var(--acc);letter-spacing:.14em}\n.tip div{font-size:11.5px;line-height:1.7;color:var(--tx2);align-items:center}\n.tip div b{white-space:nowrap;font-variant-numeric:tabular-nums;color:var(--tx);font-weight:600}\n.tip div > span{display:inline-flex;align-items:center;white-space:nowrap}\n.tip .tsw{display:inline-block;width:16px;height:8px;margin-right:8px;flex:none}\n.tip .dl{margin-top:5px;padding-top:6px;border-top:1px dashed var(--bd2)}\n.legend{gap:8px}\n.legend button{min-height:34px;padding:0 14px 0 12px;background:color-mix(in srgb,var(--surface) 80%,transparent);border:1px solid var(--bd2);font:600 10px var(--mono);letter-spacing:.1em;box-shadow:var(--e1)}\n.legend button:hover{border-color:color-mix(in srgb,var(--tx) 30%,transparent)}\n.legend button[aria-pressed="false"]{opacity:.45;text-decoration:none}\n.legend button[aria-pressed="false"] svg{opacity:.5}\n#heroSvg text{font-family:var(--mono);letter-spacing:.02em}\n'
def rw(p, f):
    s = open(p, encoding='utf-8').read(); n = f(s)
    if n != s: open(p, 'w', encoding='utf-8').write(n); print('patched', p)
    else: print('unchanged', p)
def app(s):
    if 'HAChart.smooth' in s: return s
    for a, b in PAIRS:
        if a not in s: raise SystemExit('app.js anchor not found (file differs from expected):\n' + a[:120])
        s = s.replace(a, b, 1)
    return s
rw('site/assets/js/app.js', app)
rw('site/assets/css/site.css', lambda s: s if 'charts v2' in s else s.rstrip('\n') + '\n\n' + CSS)
print('next: python3 tests/check.py')
